    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:\n        # \u8bb0\u5f55\u65e0\u6cd5\u653e\u7f6e\u7684\u6c34\u679c\u6570\u91cf\n        result = 0\n        \n        # \u904d\u5386\u6bcf\u4e2a\u6c34\u679c\uff0c\u5c1d\u8bd5\u4e3a\u5176\u5bfb\u627e\u5408\u9002\u7684\u7bee\u5b50\n        for fruit in fruits:\n            # \u6807\u8bb0\u5f53\u524d\u6c34\u679c\u662f\u5426\u627e\u5230\u5408\u9002\u7684\u7bee\u5b50\n            found = False\n            \n            # \u904d\u5386\u7bee\u5b50\u6570\u7ec4\uff0c\u5bfb\u627e\u7b2c\u4e00\u4e2a\u80fd\u5bb9\u7eb3\u5f53\u524d\u6c34\u679c\u7684\u7bee\u5b50\n            for j in range(len(baskets)):\n                # \u82e5\u5f53\u524d\u7bee\u5b50\u5bb9\u91cf\u5927\u4e8e\u7b49\u4e8e\u6c34\u679c\u5927\u5c0f\uff0c\u8bf4\u660e\u53ef\u4ee5\u653e\u7f6e\n                if fruit <= baskets[j]:\n                    # \u5c06\u8be5\u7bee\u5b50\u6807\u8bb0\u4e3a\u5df2\u4f7f\u7528\uff08\u5bb9\u91cf\u8bbe\u4e3a0\uff0c\u907f\u514d\u91cd\u590d\u4f7f\u7528\uff09\n                    baskets[j] = 0\n                    # \u6807\u8bb0\u4e3a\u627e\u5230\u5408\u9002\u7684\u7bee\u5b50\n                    found = True\n                    # \u627e\u5230\u540e\u8df3\u51fa\u5faa\u73af\uff0c\u65e0\u9700\u68c0\u67e5\u540e\u7eed\u7bee\u5b50\n                    break\n            \n            # \u82e5\u672a\u627e\u5230\u5408\u9002\u7684\u7bee\u5b50\uff0c\u65e0\u6cd5\u653e\u7f6e\u7684\u6c34\u679c\u6570\u52a01\n            if not found:\n                result += 1\n        \n        return result\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.numOfUnplacedFruits(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
